-- ---------------------------------------------------------------- v0.29.0: рейтинги и «кто в игре»
-- online_at — когда открытая игра подала знак в последний раз (presence_ping раз в ~45 с, пока вкладка видна).
alter table public.profiles add column if not exists online_at timestamptz;
create index if not exists profiles_online_at_idx on public.profiles (online_at) where online_at is not null;

create or replace function public.presence_ping() returns void language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  update profiles set online_at = now(), last_seen_at = now() where id = auth.uid() and (online_at is null or online_at < now() - interval '15 seconds');
end $$;

-- Три таблицы за один запрос (по 50 мест и место самого игрока): уровень героя; лучшая победа (уровень побеждённого монстра,
-- при равенстве — ранг типа, затем здоровье); арена — рейтинг Дуэли текущего сезона. Попадают игроки с ником. Лучшая победа считается по
-- побеждённым точкам боя (player_world 'enemy') и правилам _game_rules()->'ratings', поэтому видна и у старых игроков.
create or replace function public.ratings_board() returns jsonb language plpgsql stable security definer set search_path = public as $$
declare u uuid := auth.uid(); rr jsonb := _game_rules() -> 'ratings'; d jsonb := _game_rules() -> 'duel'; top int := (rr ->> 'top')::int; season numeric; res jsonb;
begin
  if u is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  season := greatest(0, floor(((extract(epoch from now()) * 1000) - (d ->> 'seasonStartMs')::numeric) / (d ->> 'seasonMs')::numeric));
  with
  lv as (
    select p.user_id, f.nickname, f.hero_id, p.hero_level lvl, p.hero_xp xp,
           row_number() over (order by p.hero_level desc, p.hero_xp desc, f.created_at, f.nickname) n
      from player_progress p join profiles f on f.id = p.user_id where f.nickname is not null),
  mk as (
    select distinct on (w.user_id) w.user_id, s.enemy, (rr -> 'levels' ->> s.enemy)::numeric lvl, coalesce((rr -> 'rank' ->> s.enemy)::numeric, 0) strength, coalesce((rr -> 'power' ->> s.enemy)::numeric, 0) pow
      from player_world w, lateral (select rr -> 'spawns' ->> w.key enemy) s
     where w.kind = 'enemy' and rr -> 'levels' ->> s.enemy is not null
     order by w.user_id, (rr -> 'levels' ->> s.enemy)::numeric desc, coalesce((rr -> 'rank' ->> s.enemy)::numeric, 0) desc, coalesce((rr -> 'power' ->> s.enemy)::numeric, 0) desc),
  mb as (
    select mk.user_id, f.nickname, f.hero_id, mk.enemy, mk.lvl, mk.pow, row_number() over (order by mk.lvl desc, mk.strength desc, mk.pow desc, f.created_at, f.nickname) n
      from mk join profiles f on f.id = mk.user_id where f.nickname is not null),
  ar as (
    select w.user_id, f.nickname, f.hero_id, (w.data ->> 'rating')::numeric rating, coalesce(_num(w.data -> 'wins'), 0) wins, coalesce(_num(w.data -> 'losses'), 0) losses
      from player_world w join profiles f on f.id = w.user_id
     where w.kind = 'object' and w.key = 'duel' and _num(w.data -> 'season') = season and _num(w.data -> 'rating') is not null
       and coalesce(_num(w.data -> 'wins'), 0) + coalesce(_num(w.data -> 'losses'), 0) > 0 and f.nickname is not null),
  ab as (select ar.*, row_number() over (order by rating desc, wins desc, nickname) n from ar)
  select jsonb_build_object(
    'level', jsonb_build_object(
      'top', coalesce((select jsonb_agg(jsonb_build_object('rank', n, 'nickname', nickname, 'hero', hero_id, 'level', lvl, 'xp', xp, 'me', user_id = u) order by n) from lv where n <= top), '[]'::jsonb),
      'me', (select jsonb_build_object('rank', n, 'level', lvl, 'xp', xp) from lv where user_id = u)),
    'monster', jsonb_build_object(
      'top', coalesce((select jsonb_agg(jsonb_build_object('rank', n, 'nickname', nickname, 'hero', hero_id, 'enemy', enemy, 'level', lvl, 'me', user_id = u) order by n) from mb where n <= top), '[]'::jsonb),
      'me', (select jsonb_build_object('rank', n, 'enemy', enemy, 'level', lvl) from mb where user_id = u)),
    'arena', jsonb_build_object('season', season,
      'endsAt', to_timestamp(((d ->> 'seasonStartMs')::numeric + (season + 1) * (d ->> 'seasonMs')::numeric) / 1000),
      'top', coalesce((select jsonb_agg(jsonb_build_object('rank', n, 'nickname', nickname, 'hero', hero_id, 'rating', rating, 'wins', wins, 'losses', losses, 'me', user_id = u) order by n) from ab where n <= top), '[]'::jsonb),
      'me', (select jsonb_build_object('rank', n, 'rating', rating, 'wins', wins, 'losses', losses) from ab where user_id = u)),
    'at', now())
    into res;
  return res;
end $$;

-- Кто сейчас в игре: ник, герой, уровень, в бою ли; гостей без ника — только числом.
create or replace function public.online_players() returns jsonb language plpgsql stable security definer set search_path = public as $$
declare u uuid := auth.uid(); win numeric := (_game_rules() -> 'ratings' ->> 'onlineSec')::numeric; res jsonb;
begin
  if u is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  with o as (
    select f.id, f.nickname, f.hero_id, p.hero_level lvl, p.combat_since is not null fighting
      from profiles f left join player_progress p on p.user_id = f.id
     where f.online_at > now() - make_interval(secs => win))
  select jsonb_build_object('count', (select count(*) from o), 'guests', (select count(*) from o where nickname is null),
    'players', coalesce((select jsonb_agg(jsonb_build_object('nickname', nickname, 'hero', hero_id, 'level', lvl, 'fighting', fighting, 'me', id = u) order by lvl desc nulls last, nickname)
                           from (select * from o where nickname is not null order by lvl desc nulls last, nickname limit 100) z), '[]'::jsonb),
    'at', now())
    into res;
  return res;
end $$;
revoke all on function public.presence_ping(), public.ratings_board(), public.online_players() from public, anon;
grant execute on function public.presence_ping(), public.ratings_board(), public.online_players() to authenticated;

alter table public.profiles add column if not exists player_id bigint generated always as identity;
create unique index if not exists profiles_player_id_key on public.profiles(player_id);
create table if not exists public.hero_enemy_catalog (
  enemy text primary key, level int not null check(level between 1 and 100),
  difficulty text not null check(difficulty in ('normal','elite','boss')), rank int not null unique
);
create table if not exists public.hero_enemy_spawns (
  spawn text primary key, enemy text not null references public.hero_enemy_catalog(enemy)
);
create table if not exists public.hero_victories (
  user_id uuid not null references public.profiles(id) on delete cascade,
  enemy text not null references public.hero_enemy_catalog(enemy),
  spawn text not null, won_at timestamptz, hero_level int check(hero_level between 1 and 100),
  primary key(user_id,enemy), check((won_at is null)=(hero_level is null))
);
alter table public.hero_enemy_catalog enable row level security;
alter table public.hero_enemy_spawns enable row level security;
alter table public.hero_victories enable row level security;
revoke all on public.hero_enemy_catalog, public.hero_enemy_spawns, public.hero_victories from public,anon,authenticated;
